185	        assert_eq!(
186	            line,
187	            "import type { \"default\" as CaliperComponent3 } from \"/p/src/Poly.tsx\"; export type CaliperProbe3 = \
188	             Parameters<typeof CaliperComponent3<\"div\">>[0];"
189	        );
190	    }
191	
192	    #[test]
