198	        assert!(line.contains(r#"from "C:\\p\\a\"b.tsx";"#), "{line}");
199	    }
200	
201	    /// `TSRS_BIN`, else `CALIPER_TEST_TSC`; `None` skips, which on CI is a failure (as in `tests/instantiate.rs`).
202	    #[allow(clippy::print_stderr, reason = "a skipped test says so")]
203	    fn real_checker() -> Option<camino::Utf8PathBuf> {
