245	            outcome
246	        });
247	
248	        assert_eq!(outcome.fallbacks, []);
249	        let names = |display: &str| -> Vec<String> {
250	            let component = outcome.components.iter().find(|c| c.display_name == display).expect("answered");
251	            component.props.iter().map(|prop| prop.name.clone()).collect()
252	        };
253	        let (div, a) = (names("Poly<div>"), names("Poly<a>"));
254	        assert!(div.len() >= 260, "Poly<\"div\"> has {} props", div.len());
255	        assert_ne!(div, a);
256	        assert!(a.contains(&"href".to_string()) && !div.contains(&"href".to_string()));
