5	/// The binaries searched for in each `node_modules`, in order of precedence: `typescript@7.1`'s `tsc`, then the `tsrs`
6	/// Node shim. An install that has both keeps using `typescript`, as before `tsrs` was supported; `--tsc-path` picks
7	/// the other.
8	const CANDIDATES: [[&str; 3]; 2] = [["typescript", "bin", "tsc"], ["tsrs", "bin", "tsrs"]];
9	
10	/// `explicit` if given (it must exist), else the binary of the nearest `node_modules` at or above `project_root` that
11	/// holds one: `typescript/bin/tsc`, else `tsrs/bin/tsrs`. The version is checked later, when the process is spawned.
12	pub(crate) fn find_tsc(project_root: &Utf8Path, explicit: Option<&Utf8Path>) -> Result<Utf8PathBuf, String> {
13	    if let Some(path) = explicit {
