1	//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
2	//! properties.
3	
4	use std::sync::Arc;
5	
6	use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp};
7	
8	use crate::Target;
9	use crate::convert::{Converter, declared_in, without_undefined};
10	use crate::instantiate::{self, Instantiation};
11	use crate::rpc::{CallError, Rpc, SignatureKind, SymbolInfo, TypeInfo, flag};
12	
13	pub(crate) enum Answer {
14	    Props(Vec<Arc<SemanticProp>>),
15	    /// The component keeps its structural result, for this reason.
16	    Fallback(String),
17	    /// A generic component, whose props are read from an instantiation of it ([`crate::instantiate`]).
18	    Instantiate(Instantiation),
19	}
20	
21	/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
22	/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
23	fn is_react_declared(property: &SymbolInfo) -> bool {
24	    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
25	}
26	
27	/// The export names a component may have. A display name is not always the export: Mantine sets
28	/// `displayName = "@mantine/core/Accordion"` on the export `Accordion`, and a static one reads `Menu.Item`.
29	fn candidate_names(display_name: &str) -> Vec<&str> {
30	    let mut names = vec![display_name];
31	    for separator in ['/', '.'] {
32	        if let Some((_, last)) = display_name.rsplit_once(separator)
33	            && !last.is_empty()
34	            && !names.contains(&last)
35	        {
36	            names.push(last);
37	        }
38	    }
39	    names
40	}
41	
42	fn fallback(reason: &str) -> Result<Answer, CallError> {
43	    Ok(Answer::Fallback(reason.to_string()))
44	}
45	
46	pub(crate) async fn props_of(
47	    rpc: &Rpc,
48	    converter: &Converter,
49	    interner: &PropInterner,
50	    exports: &[SymbolInfo],
51	    target: &Target,
52	) -> Result<Answer, CallError> {
53	    let display_name = target.display_name.as_str();
54	    let export = candidate_names(display_name)
55	        .into_iter()
56	        .find_map(|name| exports.iter().find(|symbol| symbol.name == name))
57	        .or_else(|| exports.iter().find(|symbol| symbol.name == "default"));
58	    let Some(export) = export else { return fallback("not found among the module's exports") };
59	
60	    let mut reference = export.reference.clone();
61	    if export.flags & flag::SYMBOL_ALIAS != 0 {
62	        reference = rpc.aliased_symbol(&reference).await?.reference;
63	    }
64	
65	    let component = rpc.type_of_symbol(&reference).await?;
66	    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
67	    let [signature] = signatures.as_slice() else {
68	        return fallback(if signatures.is_empty() {
69	            "no call signature (class or non-function component)"
70	        } else {
71	            "overloaded call signatures"
72	        });
73	    };
