/// component that has no identifier of its own — e.g. `button-group.tsx` →
/// `ButtonGroup`, `useButton.tsx` → `UseButton`. Splits on any non-alphanumeric
/// separator (`-`, `_`, `.`, space) and capitalizes each segment's first
/// character. Returns `None` when the path has no usable stem at all (e.g.
/// nothing but separators).
pub(super) fn pascal_case_from_file_stem(file_path: &Utf8Path) -> Option<String> {
    let stem = file_path.file_stem()?;
    let mut pascal = String::new();
    for segment in stem.split(|c: char| !c.is_alphanumeric()) {
        let mut chars = segment.chars();
        if let Some(first) = chars.next() {
            pascal.extend(first.to_uppercase());
            pascal.push_str(chars.as_str());
        }
    }
    (!pascal.is_empty()).then_some(pascal)
}

/// Whether `s` is written as a component or class name: an uppercase letter first, after any leading underscores and the
/// digits that follow them. An identifier cannot start with a digit, so `3D.tsx` exports `_3D`, and Mantine writes an
/// implementation component as `_Box`. `_helper` and `_3d` are not, which keeps a private function out of the candidates.
pub(super) fn is_pascal_case(s: &str) -> bool {
    let name = s.trim_start_matches('_');
    let name = if name.len() < s.len() { name.trim_start_matches(|c: char| c.is_ascii_digit()) } else { name };
    name.chars().next().is_some_and(char::is_uppercase)
}

/// Whether `name` is written as a constant, `MENU_OPTIONS` or `ORIGIN`: more than one letter and none lowercase. Such a
/// binding is not reported as a component candidate that failed to qualify; a rule that does match it still maps it.
pub(super) fn is_constant_name(name: &str) -> bool {
    name.chars().count() > 1 && !name.chars().any(char::is_lowercase)
}
    if (props) return checker.getTypeOfSymbol(props)
  }
  return undefined
}

/** A file's stem in PascalCase, the name Caliper gives a default export that has none of its own
 * (`pascal_case_from_file_stem` in crates/core/src/extractor/component.rs): `button-group.tsx` is `ButtonGroup`. */
function pascalCaseFromFile(file: string): string | undefined {
  const base = file.split('/').at(-1) ?? ''
  const dot = base.lastIndexOf('.')
  const stem = dot > 0 ? base.slice(0, dot) : base
  const pascal = stem
    .split(/[^\p{L}\p{N}]/u)

